static lstr L1215 = {0, 644, "// std/internal/host. The operating system and the machine the C compiler builds for.\012\012// 0 when the system is not one of the supported targets, else 1 for macOS, 2 for Linux and 3 for Windows.\012static int64_t narra_host_os(void) {\012#if defined(__APPLE__)\012  return 1;\012#elif defined(__linux__)\012  return 2;\012#elif defined(_WIN32)\012  return 3;\012#else\012  return 0;\012#endif\012}\012\012// 0 when the machine is not one of the supported targets, else 1 for Arm64 and 2 for X86_64.\012static int64_t narra_host_arch(void) {\012#if defined(__aarch64__) || defined(__arm64__)\012  return 1;\012#elif defined(__x86_64__) || defined(__amd64__)\012  return 2;\012#else\012  return 0;\012#endif\012}\012"};
