static lstr L10757 = {0, 1108, "// std/option: helpers over the prelude Option.\012\012export function map<T, U, effect E>(\012  option: Option<T>,\012  f: (value: T) => U uses E,\012): Option<U> uses alloc, E {\012  return match (option) { Some(value) => Some(f(value)), None => None }\012}\012\012export function andThen<T, U, effect E>(\012  option: Option<T>,\012  f: (value: T) => Option<U> uses E,\012): Option<U> uses E {\012  return match (option) { Some(value) => f(value), None => None }\012}\012\012export function withDefault<T>(option: Option<T>, fallback: T): T from option {\012  return match (option) { Some(value) => value, None => copy(fallback) }\012}\012\012export function orElse<T, effect E>(\012  option: Option<T>,\012  f: () => Option<T> uses E,\012): Option<T> from option uses E {\012  return match (option) { Some(_) => option, None => f() }\012}\012\012export function isSome<T>(option: Option<T>): bool {\012  return option is Some(_)\012}\012\012export function isNone<T>(option: Option<T>): bool {\012  return option is None\012}\012\012export function okOr<T, F>(option: Option<T>, error: F): Result<T, F> from option uses alloc {\012  return match (option) { Some(value) => Ok(value), None => Err(copy(error)) }\012}\012"};
